if (!msg.payload) return null;

const buffer = Buffer.from(msg.payload.data);
msg.payload = "data:image/jpeg;base64," + buffer.toString("base64");

return msg;

msg.payload = {
    header: {
        stamp: {
            sec: Math.floor(Date.now() / 1000),
            nanosec: (Date.now() % 1000) * 1e6
        },
        frame_id: ""
    },
    twist: {
        linear: { x: msg.payload.linear, y: 0.0, z: 0.0 },
        angular: { x: 0.0, y: 0.0, z: msg.payload.angular }
    }
};

return msg;
